import { Component, Input, TemplateRef, ViewEncapsulation } from '@angular/core';
import { MatCardModule } from '@angular/material/card';
import { NgClass, NgFor, NgIf, NgSwitch, NgSwitchCase, NgSwitchDefault, NgTemplateOutlet } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';

export type DscCardTitleAvatarSize = 'large' | 'medium' | 'small';

export type DscCardVariant = 'neutral' | 'highlight';

export type DscCardAppearance = 'outlined' | 'raised';

export type DscCardTitleAvatar = {
  imgSrc?: string;

  icon?: string;

  size?: DscCardTitleAvatarSize;

  color?: string;
}

export type DscCardTitle = {
  variant?: DscCardVariant;

  text: string;

  subtext?: string;

  avatar?: DscCardTitleAvatar;

  headingLevelTitle?: string;

  headingLevelSubtitle?: string;
}

export type DscCardContent = {
  text?: string;

  template?: TemplateRef<any>;
}

export type DscCardImage = {
  src: string;

  alt: string;

  enableMargin?: boolean;

  topPosition?: boolean;
}

export type DscCardFooter = {
  showDivider?: boolean;

  template: TemplateRef<any>;
}

export type DscCardData = {
  appearance?: DscCardAppearance;

  interative?: boolean;

  focusable?: boolean;

  title?: DscCardTitle;

  image?: DscCardImage;

  content?: DscCardContent;

  footer?: DscCardFooter;
}

@Component({
  selector: 'dsc-card',
  standalone: true,
  imports: [MatCardModule, NgIf, NgTemplateOutlet, MatIconModule, NgClass, NgSwitch, NgSwitchDefault, NgSwitchCase, NgFor],
  encapsulation: ViewEncapsulation.None,
  templateUrl: './dsc-card.component.html',
  styleUrls: ['./dsc-card.component.scss']
})
export class DscCardComponent {
  @Input()
  data!: DscCardData;

  @Input() iconStyle: 'outlined' | 'filled' | 'rounded' | 'sharp' | 'two-tone' = 'filled';

  getIconClass(): string {
    if (this.iconStyle === 'filled') return 'material-icons';
    if (this.iconStyle === 'rounded') return 'material-icons-round';
    return `material-icons-${this.iconStyle}`;
  }

  
  getHeadingTagTitle(level?: string): string {
    const validLevels = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'];
    return validLevels.includes(level || '') ? level! : 'h3';
  }

  getHeadingTagSubtitle(level?: string): string {
    const validLevels = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'];
    return validLevels.includes(level || '') ? level! : 'h4';
  }

  getTitleHtml(): string {
    if (!this.data?.title) return '';
    const tag = this.getHeadingTagTitle(this.data.title.headingLevelTitle);
    const classes = [
      'mat-mdc-card-title',
      this.data.title.variant === 'highlight'
        ? 'mat-mdc-card-title--highlight'
        : 'mat-mdc-card-title--neutral'
    ].join(' ');
    return `<${tag} class="${classes}" role="heading" aria-level="${tag.replace('h', '')}">
              ${this.data.title.text}
            </${tag}>`;
  }

  getSubtitleHtml(): string {
    if (!this.data?.title?.subtext) return '';
    const tag = this.getHeadingTagSubtitle(this.data.title.headingLevelSubtitle);
    return `<${tag} class="mat-mdc-card-subtitle">${this.data.title.subtext}</${tag}>`;
  }

}
